const CATALOGO = {"P01": {"codigo": "P01", "nome": "Tomate pelado italiano", "unidade": "kg", "consumo_semanal": 30, "estoque": 8, "ultimo_preco": 16.5}, "P02": {"codigo": "P02", "nome": "Muçarela de búfala", "unidade": "kg", "consumo_semanal": 12, "estoque": 3, "ultimo_preco": 78.0}, "P03": {"codigo": "P03", "nome": "Parmesão Grana Padano", "unidade": "kg", "consumo_semanal": 6, "estoque": 2, "ultimo_preco": 135.0}, "P04": {"codigo": "P04", "nome": "Farinha de trigo tipo 00", "unidade": "kg", "consumo_semanal": 50, "estoque": 15, "ultimo_preco": 9.8}, "P05": {"codigo": "P05", "nome": "Azeite extravirgem", "unidade": "L", "consumo_semanal": 10, "estoque": 4, "ultimo_preco": 52.0}, "P06": {"codigo": "P06", "nome": "Guanciale", "unidade": "kg", "consumo_semanal": 4, "estoque": 1, "ultimo_preco": 145.0}, "P07": {"codigo": "P07", "nome": "Filé mignon limpo", "unidade": "kg", "consumo_semanal": 15, "estoque": 4, "ultimo_preco": 89.0}, "P08": {"codigo": "P08", "nome": "Camarão VG limpo", "unidade": "kg", "consumo_semanal": 8, "estoque": 2, "ultimo_preco": 115.0}, "P09": {"codigo": "P09", "nome": "Rúcula", "unidade": "maço", "consumo_semanal": 40, "estoque": 10, "ultimo_preco": 3.5}, "P10": {"codigo": "P10", "nome": "Manjericão", "unidade": "maço", "consumo_semanal": 30, "estoque": 5, "ultimo_preco": 4.0}, "P11": {"codigo": "P11", "nome": "Limão tahiti", "unidade": "kg", "consumo_semanal": 10, "estoque": 3, "ultimo_preco": 6.0}, "P12": {"codigo": "P12", "nome": "Cebola", "unidade": "kg", "consumo_semanal": 20, "estoque": 6, "ultimo_preco": 5.2}, "P13": {"codigo": "P13", "nome": "Alho descascado", "unidade": "kg", "consumo_semanal": 4, "estoque": 1, "ultimo_preco": 32.0}, "P14": {"codigo": "P14", "nome": "Creme de leite fresco", "unidade": "L", "consumo_semanal": 12, "estoque": 4, "ultimo_preco": 24.0}, "P15": {"codigo": "P15", "nome": "Ovos", "unidade": "un", "consumo_semanal": 360, "estoque": 90, "ultimo_preco": 0.85}, "P16": {"codigo": "P16", "nome": "Manteiga sem sal", "unidade": "kg", "consumo_semanal": 6, "estoque": 2, "ultimo_preco": 58.0}, "P17": {"codigo": "P17", "nome": "Batata", "unidade": "kg", "consumo_semanal": 25, "estoque": 8, "ultimo_preco": 6.5}, "P18": {"codigo": "P18", "nome": "Água mineral sem gás 500 ml", "unidade": "un", "consumo_semanal": 240, "estoque": 60, "ultimo_preco": 1.4}};
// Porte de cotador/regras.py para o nó Code do n8n. Testado contra a versão Python em n8n/testar_normalizar.py.
const CONVERSAO = { kg: ['kg', 1], g: ['kg', 0.001], L: ['L', 1], ml: ['L', 0.001], un: ['un', 1], 'dúzia': ['un', 12], 'maço': ['maço', 1] };
const LIMITE_VARIACAO = 0.35;
const arred = (v, c) => Math.round(v * 10 ** c) / 10 ** c;

function normalizar(item, catalogo) {
  const r = { ...item, pendencias: [] };
  const cod = item.codigo_catalogo;
  if (cod === null) { r.status = 'fora_catalogo'; return r; }
  if (!catalogo[cod]) { r.status = 'revisao'; r.pendencias.push(`código ${cod} não existe no catálogo`); return r; }
  if (!item.disponivel || item.preco === null) { r.status = 'indisponivel'; return r; }
  const base = catalogo[cod].unidade;
  const qtd = item.quantidade_na_embalagem, un = item.unidade_da_quantidade;
  if (qtd === null || un === null) { r.status = 'revisao'; r.pendencias.push('embalagem sem tamanho'); return r; }
  const [unBase, fator] = CONVERSAO[un] || [null, null];
  if (unBase !== base) { r.status = 'revisao'; r.pendencias.push(`unidade ${un} não converte para ${base}`); return r; }
  const tamanho = qtd * fator;
  r.embalagem_em_base = arred(tamanho, 6);
  r.preco_base = item.preco_refere_a === 'embalagem' ? arred(item.preco / tamanho, 4) : item.preco;
  if (item.preco_refere_a === 'unidade') r.embalagem_em_base = null;
  const ultimo = catalogo[cod].ultimo_preco;
  const v = r.preco_base / ultimo - 1;
  r.variacao_vs_ultimo = arred(v, 4);
  if (Math.abs(v) > LIMITE_VARIACAO) {
    const pct = `${v >= 0 ? '+' : '-'}${Math.round(Math.abs(v) * 100)}%`;
    r.pendencias.push(`preço ${pct} em relação ao último pago (R$ ${ultimo.toFixed(2).replace('.', ',')}/${base})`);
  }
  if (item.confianca === 'baixa') r.pendencias.push('confiança baixa na leitura' + (item.observacao ? `: ${item.observacao}` : ''));
  r.status = r.pendencias.length ? 'revisao' : 'ok';
  return r;
}
function conferirCondicoes(cond) {
  const frases = (cond.trechos || []).flatMap(t => t.replace(/;/g, '.').split('.')).map(f => f.toLowerCase());
  const trechos = frases.join(' ');
  const avisos = [];
  const freteCond = frases.some(f => f.includes('frete') && ['abaixo de', 'acima de', 'a partir de'].some(k => f.includes(k)));
  if (freteCond && cond.frete_gratis_acima_de == null)
    avisos.push('o texto fala de frete condicionado a um valor, mas o limite do frete grátis não foi registrado');
  if (trechos.includes('desconto') && cond.desconto_percentual == null)
    avisos.push('o texto fala de desconto, mas o percentual não foi registrado');
  // "não tem pedido mínimo" / "sem pedido mínimo" não conta
  const falaMinimo = frases.some(f => f.replace(/minimo/g, 'mínimo').includes('mínimo') && !(f.includes('não') || f.includes('nao ') || f.includes('sem ')));
  if (falaMinimo && cond.pedido_minimo == null)
    avisos.push('o texto fala de pedido mínimo, mas o valor não foi registrado');
  return avisos;
}
if (typeof module !== 'undefined') module.exports = { normalizar, conferirCondicoes };

const bloco = $input.first().json.content.find(b => b.type === 'tool_use');
const cot = bloco.input;
const itens = cot.itens.map(i => normalizar(i, CATALOGO));
const linhas = itens.map(i => ({
  json: { data: $now.toFormat('yyyy-MM-dd'), fornecedor: cot.fornecedor, codigo: i.codigo_catalogo, texto: i.texto_original,
          preco_cotado: i.preco, embalagem: i.embalagem, preco_base: i.preco_base ?? null, status: i.status,
          pendencias: (i.pendencias || []).join('; '), pedido_minimo: cot.condicoes.pedido_minimo,
          frete: cot.condicoes.frete_valor,
          alertas: [...(cot.alertas || []), ...conferirCondicoes(cot.condicoes)].join(' | ') }
}));
return linhas;

// Junta os itens que precisam de revisão humana num e-mail para o comprador.
const pend = $input.all().map(x => x.json).filter(x => x.status === 'revisao' || x.alertas);
if (!pend.length) return [];
const corpo = pend.map(p => `• ${p.fornecedor}: "${p.texto}" -> ${p.pendencias || ''} ${p.alertas ? 'ALERTA: ' + p.alertas : ''}`).join('\n');
return [{ json: { assunto: `Cotação: ${pend.length} item(ns) para revisar`, corpo } }];
